{{-- One portfolio project: $p is the row being edited, or null for a new one; $sfx keeps ids unique. --}}
<div class="ix-form__row"><label class="ix-label" for="p_title_{{ $sfx }}">Project</label><input class="ix-input" id="p_title_{{ $sfx }}" name="title" minlength="2" maxlength="140" required value="{{ $p ? $p->title : old('title') }}" placeholder="For example: Borehole for a Lowveld citrus farm"></div>
<div class="ix-form__row"><label class="ix-label" for="p_sum_{{ $sfx }}">What you did <span class="ix-hint">optional</span></label><textarea class="ix-input" id="p_sum_{{ $sfx }}" name="summary" rows="3" maxlength="1200">{{ $p ? $p->summary : old('summary') }}</textarea></div>
<div class="ix-form__row"><label class="ix-label" for="p_year_{{ $sfx }}">Year <span class="ix-hint">optional</span></label><input class="ix-input" type="number" id="p_year_{{ $sfx }}" name="year" min="1900" max="{{ now()->year }}" value="{{ $p ? $p->year : old('year') }}"></div>
<div class="ix-form__row"><label class="ix-label" for="p_loc_{{ $sfx }}">Where <span class="ix-hint">optional</span></label><input class="ix-input" id="p_loc_{{ $sfx }}" name="location" maxlength="120" value="{{ $p ? $p->location : old('location') }}"></div>
<div class="ix-form__row"><label class="ix-label" for="p_img_{{ $sfx }}">{{ $p ? 'Add a picture' : 'Picture' }} <span class="ix-hint">optional; up to six per project</span></label><input class="ix-input" type="file" id="p_img_{{ $sfx }}" name="image" accept="image/jpeg,image/png,image/webp,image/gif"></div>
<div class="ix-form__row"><label class="ix-label" for="p_cap_{{ $sfx }}">Caption <span class="ix-hint">what the picture shows</span></label><input class="ix-input" id="p_cap_{{ $sfx }}" name="caption" maxlength="500"></div>
